import sqlite3 from 'sqlite3';

const dbPath = '/home/user/qwik-app/database.sqlite';

class Mutex {
  private queue: (() => void)[] = [];
  private locked = false;

  async acquire(): Promise<() => void> {
    if (!this.locked) {
      this.locked = true;
      return () => this.release();
    }
    return new Promise<() => void>((resolve) => {
      this.queue.push(() => resolve(() => this.release()));
    });
  }

  private release() {
    if (this.queue.length > 0) {
      const next = this.queue.shift();
      next?.();
    } else {
      this.locked = false;
    }
  }
}

export const dbMutex = new Mutex();

let dbInstance: sqlite3.Database | null = null;
let initPromise: Promise<sqlite3.Database> | null = null;

export function getDb(): Promise<sqlite3.Database> {
  if (initPromise) {
    return initPromise;
  }

  initPromise = new Promise((resolve, reject) => {
    const db = new sqlite3.Database(dbPath, (err) => {
      if (err) {
        initPromise = null;
        reject(err);
        return;
      }

      // Configure busy timeout
      db.run("PRAGMA busy_timeout = 30000", (pragmaErr) => {
        if (pragmaErr) {
          initPromise = null;
          reject(pragmaErr);
          return;
        }

        db.run(
          `CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL,
            age INTEGER NOT NULL
          )`,
          (createErr) => {
            if (createErr) {
              initPromise = null;
              reject(createErr);
            } else {
              dbInstance = db;
              resolve(db);
            }
          }
        );
      });
    });
  });

  return initPromise;
}

export function dbAll<T>(db: sqlite3.Database, sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows as T[]);
    });
  });
}

export function dbRun(db: sqlite3.Database, sql: string, params: any[] = []): Promise<sqlite3.RunResult> {
  return new Promise((resolve, reject) => {
    db.run(sql, params, function (this: sqlite3.RunResult, err) {
      if (err) reject(err);
      else resolve(this);
    });
  });
}

export function parseCSV(text: string): string[][] {
  const result: string[][] = [];
  let row: string[] = [];
  let curr = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i + 1];

    if (inQuotes) {
      if (char === '"') {
        if (nextChar === '"') {
          // Escaped quote
          curr += '"';
          i++; // Skip next quote
        } else {
          // End of quote
          inQuotes = false;
        }
      } else {
        curr += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        row.push(curr);
        curr = '';
      } else if (char === '\r' && nextChar === '\n') {
        row.push(curr);
        curr = '';
        result.push(row);
        row = [];
        i++; // Skip \n
      } else if (char === '\n') {
        row.push(curr);
        curr = '';
        result.push(row);
        row = [];
      } else {
        curr += char;
      }
    }
  }

  // Handle last field/row if not followed by a newline
  if (curr !== '' || row.length > 0) {
    row.push(curr);
    result.push(row);
  }

  return result;
}

export function isRowEmpty(row: string[]): boolean {
  return row.length === 0 || (row.length === 1 && row[0].trim() === '');
}

export function isValidEmail(email: string): boolean {
  if (!email) return false;
  const trimmed = email.trim();
  if (!trimmed) return false;

  const parts = trimmed.split('@');
  if (parts.length !== 2) return false;

  const [username, domain] = parts;
  if (!username || !username.trim()) return false;
  if (!domain || !domain.trim()) return false;

  const domainParts = domain.split('.');
  if (domainParts.length < 2) return false;
  for (const part of domainParts) {
    if (!part || !part.trim()) return false;
  }

  if (/\s/.test(username) || /\s/.test(domain)) return false;

  return true;
}

export function isValidAge(ageStr: string): boolean {
  const trimmed = ageStr.trim();
  if (!/^\d+$/.test(trimmed)) {
    return false;
  }
  const age = parseInt(trimmed, 10);
  return age >= 0;
}

import { type RequestHandler } from '@builder.io/qwik-city';
import { getDb, dbRun, dbMutex } from '../../utils/db';
import { parseCSV, isRowEmpty, isValidEmail, isValidAge } from '../../utils/csv';

export const onPost: RequestHandler = async (event) => {
  try {
    const formData = await event.request.formData();
    const file = formData.get('file');

    if (!file || typeof file === 'string') {
      return event.json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: ["No file uploaded"]
          }
        ]
      });
    }

    const csvContent = await (file as any).text();
    const rawRows = parseCSV(csvContent);
    const rows = rawRows.filter(row => !isRowEmpty(row));

    if (rows.length === 0) {
      return event.json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: ["CSV file is empty"]
          }
        ]
      });
    }

    // Header row is rows[0]
    const header = rows[0];
    const nameIdx = header.indexOf('Name');
    const emailIdx = header.indexOf('Email');
    const ageIdx = header.indexOf('Age');

    if (nameIdx === -1 || emailIdx === -1 || ageIdx === -1) {
      return event.json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: ["Missing required columns: Name, Email, Age"]
          }
        ]
      });
    }

    const errors: { row: number; errors: string[] }[] = [];
    const validData: { name: string; email: string; age: number }[] = [];

    // Process rows starting from index 1 (excluding header row)
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];

      const name = row[nameIdx] !== undefined ? row[nameIdx] : '';
      const email = row[emailIdx] !== undefined ? row[emailIdx] : '';
      const ageStr = row[ageIdx] !== undefined ? row[ageIdx] : '';

      const rowErrors: string[] = [];

      if (!name || name.trim() === '') {
        rowErrors.push("Name cannot be empty");
      }
      if (!isValidEmail(email)) {
        rowErrors.push("Invalid email format");
      }
      if (!isValidAge(ageStr)) {
        rowErrors.push("Age must be an integer >= 0");
      }

      if (rowErrors.length > 0) {
        errors.push({
          row: i, // i is the 1-based index of the data row excluding the header
          errors: rowErrors
        });
      } else {
        validData.push({
          name: name.trim(),
          email: email.trim(),
          age: parseInt(ageStr.trim(), 10)
        });
      }
    }

    if (errors.length > 0) {
      errors.sort((a, b) => a.row - b.row);
      return event.json(200, {
        success: false,
        imported: 0,
        errors: errors
      });
    }

    // No errors, insert into database atomically
    const db = await getDb();
    const release = await dbMutex.acquire();

    try {
      await dbRun(db, 'BEGIN TRANSACTION');
      for (const user of validData) {
        await dbRun(db, 'INSERT INTO users (name, email, age) VALUES (?, ?, ?)', [
          user.name,
          user.email,
          user.age
        ]);
      }
      await dbRun(db, 'COMMIT');

      return event.json(200, {
        success: true,
        imported: validData.length,
        errors: []
      });
    } catch (dbErr: any) {
      try {
        await dbRun(db, 'ROLLBACK');
      } catch (rollbackErr) {
        // Ignore rollback errors if transaction was already rolled back or not started
      }
      return event.json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 1,
            errors: [dbErr.message || "Database transaction error"]
          }
        ]
      });
    } finally {
      release();
    }
  } catch (err: any) {
    return event.json(200, {
      success: false,
      imported: 0,
      errors: [
        {
          row: 1,
          errors: [err.message || "An unexpected error occurred"]
        }
      ]
    });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { getDb, dbAll } from '../../utils/db';

interface UserRow {
  id: number;
  name: string;
  email: string;
  age: number;
}

export const onGet: RequestHandler = async (event) => {
  try {
    const db = await getDb();
    const users = await dbAll<UserRow>(db, 'SELECT id, name, email, age FROM users ORDER BY id ASC');
    return event.json(200, users);
  } catch (err: any) {
    return event.json(500, {
      error: err.message || "Failed to retrieve users"
    });
  }
};

